import { useEffect, useState } from 'react';
import { motion, useReducedMotion } from 'framer-motion';
import { useInView } from '@/hooks/useInView';

const CYCLE = 1.6;

/**
 * 沙漏翻转 — an hourglass outline (two triangles apex-to-apex) rotates 180°
 * every 1.6s with a spring settle. Inside, the sand: the upper triangle
 * drains (scaleY 1 → 0, origin at the apex) while the lower one fills
 * (scaleY 0 → 1); each flip swaps them, so the cycle restarts seamlessly.
 */
export default function Hourglass() {
  const reduced = useReducedMotion();
  const { ref, inView } = useInView<HTMLDivElement>();
  const [cycle, setCycle] = useState(0);

  useEffect(() => {
    if (!inView || reduced) return;
    const t = setInterval(() => setCycle((c) => c + 1), CYCLE * 1000);
    return () => clearInterval(t);
  }, [inView, reduced]);

  const drain = {
    duration: 1.05,
    delay: 0.45,
    ease: 'easeIn' as const,
  };

  return (
    <div ref={ref} className="flex h-full w-full flex-col items-center justify-center gap-5">
      <motion.div
        animate={reduced ? undefined : { rotate: cycle * 180 }}
        transition={{ type: 'spring', stiffness: 160, damping: 15 }}
        className="flex"
      >
        <svg viewBox="0 0 32 36" width={40} height={45} aria-hidden>
          {/* outline: top bulb, bottom bulb, caps */}
          <path
            d="M 5 2 H 27 M 5 34 H 27 M 6 2 L 26 2 L 16 18 Z M 6 34 L 26 34 L 16 18 Z"
            fill="none"
            stroke="#09090b"
            strokeWidth={1.6}
            strokeLinejoin="round"
            strokeLinecap="round"
          />
          {/* upper sand: drains toward the apex */}
          <motion.polygon
            key={`top-${cycle}`}
            points="8.5,4.5 23.5,4.5 16,16.5"
            fill="#09090b"
            style={{ transformBox: 'fill-box', transformOrigin: '50% 100%' }}
            initial={reduced ? undefined : { scaleY: 1 }}
            animate={reduced ? undefined : { scaleY: 0 }}
            transition={drain}
          />
          {/* lower sand: piles up from the base */}
          <motion.polygon
            key={`bottom-${cycle}`}
            points="8.5,31.5 23.5,31.5 16,19.5"
            fill="#09090b"
            style={{ transformBox: 'fill-box', transformOrigin: '50% 100%' }}
            initial={reduced ? undefined : { scaleY: 0 }}
            animate={reduced ? undefined : { scaleY: 1 }}
            transition={drain}
          />
        </svg>
      </motion.div>
      <span className="font-mono text-[11px] uppercase tracking-[0.08em] text-zinc-400">
        hourglass
      </span>
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';

/**
 * IntersectionObserver hook with enter/exit hysteresis, used to gate live previews.
 *
 * Why hysteresis: a single observer with a small rootMargin causes boundary thrash —
 * cards just inside the margin mount, then unmount the moment they scroll a few px
 * past the viewport edge, producing visible white flashes ("闪屏") while scrolling.
 *
 * - enter observer: mounts the preview 240px BEFORE it reaches the viewport,
 *   so content is already there when the user sees it.
 * - exit observer: keeps the preview mounted until it is 600px PAST the viewport,
 *   so briefly scrolling by never blanks a card.
 */
export function useInView<T extends HTMLElement>(enterMargin = '240px', exitMargin = '600px') {
  const ref = useRef<T | null>(null);
  const [inView, setInView] = useState(() => typeof IntersectionObserver === 'undefined');

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === 'undefined') return;

    const enter = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting) setInView(true);
      },
      { rootMargin: enterMargin, threshold: 0 },
    );
    const exit = new IntersectionObserver(
      (entries) => {
        if (entries[0] && !entries[0].isIntersecting) setInView(false);
      },
      { rootMargin: exitMargin, threshold: 0 },
    );

    enter.observe(el);
    exit.observe(el);
    return () => {
      enter.disconnect();
      exit.disconnect();
    };
  }, [enterMargin, exitMargin]);

  return { ref, inView };
}

